package com.asmj.marketplace.controller;

import com.asmj.marketplace.model.Role;
import com.asmj.marketplace.model.UserAccount;
import com.asmj.marketplace.model.VendorProfile;
import com.asmj.marketplace.order.*;
import com.asmj.marketplace.product.*;
import com.asmj.marketplace.repository.UserAccountRepository;
import com.asmj.marketplace.repository.VendorProfileRepository;
import com.asmj.marketplace.commission.CommissionService;
import com.asmj.marketplace.service.CloudinaryImageService;
import org.springframework.web.multipart.MultipartFile;
import jakarta.servlet.http.HttpSession;
import java.math.BigDecimal;
import java.security.Principal;
import java.time.Instant;
import java.util.*;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller
public class OrderController {
 private final ProductRepository products; private final MarketplaceOrderRepository orders; private final UserAccountRepository users; private final VendorProfileRepository profiles; private final CommissionService commissions; private final CloudinaryImageService uploads;
 public OrderController(ProductRepository p,MarketplaceOrderRepository o,UserAccountRepository u,VendorProfileRepository v,CommissionService commissions,CloudinaryImageService uploads){products=p;orders=o;users=u;profiles=v;this.commissions=commissions;this.uploads=uploads;}
 @SuppressWarnings("unchecked") private Map<String,Integer> cart(HttpSession s){Map<String,Integer> c=(Map<String,Integer>)s.getAttribute("asmjCart");if(c==null){c=new LinkedHashMap<>();s.setAttribute("asmjCart",c);}return c;}
 @PostMapping("/cart/add/{id}") public String add(@PathVariable String id,@RequestParam(defaultValue="1") int quantity,HttpSession session,RedirectAttributes ra){Product p=products.findById(id).filter(x->x.getStatus()==ProductStatus.ACTIVE).orElse(null);if(p==null){ra.addFlashAttribute("errorMessage","Product is not available.");return "redirect:/products";}if(quantity<1||quantity>50){ra.addFlashAttribute("errorMessage","Choose a quantity from 1 to 50.");return "redirect:/products";}Map<String,Integer> c=cart(session);if(!c.isEmpty()){String existingVendor=c.keySet().stream().map(products::findById).flatMap(Optional::stream).map(Product::getVendorUserId).findFirst().orElse(null);if(existingVendor!=null&&!existingVendor.equals(p.getVendorUserId())){ra.addFlashAttribute("errorMessage","Please complete or clear your current cart before ordering from another vendor. Each order is placed with one vendor.");return "redirect:/cart";}}int next=c.getOrDefault(id,0)+quantity;if(p.getStockQuantity()==null||next>p.getStockQuantity()){ra.addFlashAttribute("errorMessage","Requested quantity exceeds available stock.");return "redirect:/products";}c.put(id,next);ra.addFlashAttribute("successMessage","Product added to your cart.");return "redirect:/cart";}
 @GetMapping("/cart") public String viewCart(HttpSession s,Model m){List<Map<String,Object>> rows=new ArrayList<>();BigDecimal subtotal=BigDecimal.ZERO;String vendorId=null;for(var e:cart(s).entrySet()){Product p=products.findById(e.getKey()).orElse(null);if(p==null||p.getStatus()!=ProductStatus.ACTIVE)continue;BigDecimal line=p.getPrice().multiply(BigDecimal.valueOf(e.getValue()));subtotal=subtotal.add(line);Map<String,Object> row=new HashMap<>();row.put("product",p);row.put("quantity",e.getValue());row.put("lineTotal",line);rows.add(row);vendorId=p.getVendorUserId();}m.addAttribute("cartItems",rows);m.addAttribute("subtotal",subtotal);m.addAttribute("cartCount",cart(s).values().stream().mapToInt(Integer::intValue).sum());return "order/cart";}
 @PostMapping("/cart/update") public String update(@RequestParam String productId,@RequestParam int quantity,HttpSession s,RedirectAttributes ra){Product p=products.findById(productId).orElse(null);if(p==null||p.getStockQuantity()==null||quantity<0||quantity>p.getStockQuantity()){ra.addFlashAttribute("errorMessage","Invalid quantity.");return "redirect:/cart";}if(quantity==0)cart(s).remove(productId);else cart(s).put(productId,quantity);return "redirect:/cart";}
 @PostMapping("/cart/clear") public String clear(HttpSession s){cart(s).clear();return "redirect:/cart";}
 @GetMapping("/checkout") public String checkout(HttpSession s,Principal principal,Model m,RedirectAttributes ra){if(cart(s).isEmpty()){ra.addFlashAttribute("errorMessage","Your cart is empty.");return "redirect:/products";}UserAccount buyer=current(principal);if(buyer.getRole()!=Role.ROLE_CUSTOMER)throw new IllegalArgumentException("Please sign in with a customer account to checkout.");List<Product> ps=cart(s).keySet().stream().map(products::findById).flatMap(Optional::stream).toList();if(ps.isEmpty())return "redirect:/cart";Product p=ps.get(0);VendorProfile profile=profiles.findByUserId(p.getVendorUserId()).orElseGet(VendorProfile::new);m.addAttribute("vendorProfile",profile);m.addAttribute("vendorName",p.getVendorName());m.addAttribute("customer",buyer);m.addAttribute("cartItems",cartRows(s));m.addAttribute("subtotal",cartSubtotal(s));return "order/checkout";}
 @PostMapping("/checkout") public String place(@RequestParam String fulfilmentMethod,@RequestParam String paymentMethod,@RequestParam(required=false) String deliveryAddress,@RequestParam(required=false) String deliveryCity,@RequestParam(required=false) String deliveryState,@RequestParam(required=false) String deliveryPinCode,@RequestParam(required=false) String customerNote,@RequestParam(required=false) String upiReference,@RequestParam(required=false) MultipartFile paymentProof,Principal principal,HttpSession s,RedirectAttributes ra){
  try{if(cart(s).isEmpty())throw new IllegalArgumentException("Your cart is empty.");UserAccount buyer=current(principal);if(buyer.getRole()!=Role.ROLE_CUSTOMER)throw new IllegalArgumentException("Please sign in with a customer account to checkout.");List<Product> ps=cart(s).keySet().stream().map(id->products.findById(id).orElseThrow(()->new IllegalArgumentException("A cart product is no longer available."))).toList();String vendorId=ps.get(0).getVendorUserId();if(commissions.hasOverdueCommission(vendorId))throw new IllegalArgumentException("This vendor has an overdue marketplace commission settlement and cannot accept new orders right now. Please choose another vendor or try later.");if(ps.stream().anyMatch(p->!vendorId.equals(p.getVendorUserId())))throw new IllegalArgumentException("A single order can contain products from one vendor only.");VendorProfile profile=profiles.findByUserId(vendorId).orElseGet(VendorProfile::new);boolean delivery="DELIVERY".equals(fulfilmentMethod);if(!delivery&& !"PICKUP".equals(fulfilmentMethod))throw new IllegalArgumentException("Choose delivery or pickup.");if(delivery&&!profile.isHomeDelivery())throw new IllegalArgumentException("This vendor does not offer home delivery.");if(!delivery&&!profile.isPickupFromShop())throw new IllegalArgumentException("This vendor does not offer shop pickup.");if(delivery&&(blank(deliveryAddress)||blank(deliveryCity)||blank(deliveryState)||deliveryPinCode==null||!deliveryPinCode.matches("[0-9]{6}")))throw new IllegalArgumentException("Enter a complete delivery address and valid 6-digit PIN code.");PaymentMethod pm=PaymentMethod.valueOf(paymentMethod);if(pm==PaymentMethod.UPI&&(blank(upiReference)||upiReference.trim().length()>100))throw new IllegalArgumentException("Enter your UPI transaction reference.");if(pm==PaymentMethod.UPI&&(paymentProof==null||paymentProof.isEmpty()))throw new IllegalArgumentException("Upload your UPI payment screenshot.");
   MarketplaceOrder o=new MarketplaceOrder();o.setOrderNumber("ASMJ-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT));o.setCustomerUserId(buyer.getId());o.setCustomerName(buyer.getFullName());o.setCustomerMobile(buyer.getMobile());o.setCustomerEmail(buyer.getEmail());o.setVendorUserId(vendorId);o.setVendorName(ps.get(0).getVendorName());o.setFulfilmentMethod(fulfilmentMethod);o.setDeliveryAddress(delivery?deliveryAddress.trim():"Vendor shop pickup");o.setDeliveryCity(delivery?deliveryCity.trim():"");o.setDeliveryState(delivery?deliveryState.trim():"");o.setDeliveryPinCode(delivery?deliveryPinCode.trim():"");o.setCustomerNote(customerNote==null?"":customerNote.trim());o.setPaymentMethod(pm);o.setUpiReference(pm==PaymentMethod.UPI?upiReference.trim():null);o.setPaymentStatus(PaymentStatus.PENDING);if(pm==PaymentMethod.UPI){Map<String,Object> proof=uploads.uploadDocument(paymentProof,"asmj-marketplace/order-payments");o.setPaymentProofUrl(String.valueOf(proof.get("secure_url")));o.setPaymentProofFileName(paymentProof.getOriginalFilename());o.setPaymentStatus(PaymentStatus.PROOF_SUBMITTED);}
   BigDecimal subtotal=BigDecimal.ZERO;for(Product p:ps){int qty=cart(s).getOrDefault(p.getId(),0);if(p.getStatus()!=ProductStatus.ACTIVE||p.getStockQuantity()==null||qty<1||qty>p.getStockQuantity())throw new IllegalArgumentException("Stock changed for "+p.getName()+". Please review your cart.");OrderItem item=new OrderItem(p.getId(),p.getName(),p.getImageUrl(),qty,p.getPrice());o.getItems().add(item);subtotal=subtotal.add(item.getLineTotal());}
   BigDecimal charge=delivery?(profile.getDeliveryCharge()==null?BigDecimal.ZERO:profile.getDeliveryCharge()):BigDecimal.ZERO;if(charge.signum()<0)charge=BigDecimal.ZERO;o.setSubtotal(subtotal);o.setDeliveryCharge(charge);o.setTotal(subtotal.add(charge));o.setCreatedAt(Instant.now());o.setUpdatedAt(Instant.now());orders.save(o);
   for(Product p:ps){p.setStockQuantity(p.getStockQuantity()-cart(s).get(p.getId()));products.save(p);}cart(s).clear();ra.addFlashAttribute("successMessage","Order placed successfully. Order number: "+o.getOrderNumber());return "redirect:/customer/orders";
  }catch(IllegalArgumentException|IllegalStateException ex){ra.addFlashAttribute("errorMessage",ex.getMessage());return "redirect:/checkout";}}
 @GetMapping("/customer/orders") public String customerOrders(Principal p,Model m){UserAccount u=current(p);m.addAttribute("orders",orders.findByCustomerUserIdOrderByCreatedAtDesc(u.getId()));return "customer/orders";}
 @GetMapping("/vendor/orders") public String vendorOrders(Principal p,Model m){UserAccount u=current(p);if(u.getRole()!=Role.ROLE_VENDOR)return "auth/access-denied";m.addAttribute("orders",orders.findByVendorUserIdOrderByCreatedAtDesc(u.getId()));return "vendor/orders";}
 @GetMapping("/admin/orders") public String adminOrders(Model m){m.addAttribute("orders",orders.findAllByOrderByCreatedAtDesc());return "admin/orders";}
 @PostMapping("/vendor/orders/{id}/status") public String vendorStatus(@PathVariable String id,@RequestParam OrderStatus status,Principal p,RedirectAttributes ra){UserAccount u=current(p);if(u.getRole()!=Role.ROLE_VENDOR)return "auth/access-denied";MarketplaceOrder o=orders.findById(id).orElseThrow();if(!u.getId().equals(o.getVendorUserId()))return "auth/access-denied";if(!Set.of(OrderStatus.ACCEPTED,OrderStatus.PROCESSING,OrderStatus.READY_FOR_PICKUP,OrderStatus.OUT_FOR_DELIVERY,OrderStatus.COMPLETED,OrderStatus.CANCELLED).contains(status)){ra.addFlashAttribute("errorMessage","Invalid order status.");return "redirect:/vendor/orders";}if(o.getStatus()==OrderStatus.CANCELLED||o.getStatus()==OrderStatus.COMPLETED){ra.addFlashAttribute("errorMessage","This order is already closed.");return "redirect:/vendor/orders";}boolean allowed=(o.getStatus()==OrderStatus.PLACED&&(status==OrderStatus.ACCEPTED||status==OrderStatus.CANCELLED))||(o.getStatus()==OrderStatus.ACCEPTED&&(status==OrderStatus.PROCESSING||status==OrderStatus.CANCELLED))||(o.getStatus()==OrderStatus.PROCESSING&&((status==OrderStatus.READY_FOR_PICKUP&&"PICKUP".equals(o.getFulfilmentMethod()))||(status==OrderStatus.OUT_FOR_DELIVERY&&"DELIVERY".equals(o.getFulfilmentMethod()))||status==OrderStatus.CANCELLED))||((o.getStatus()==OrderStatus.READY_FOR_PICKUP||o.getStatus()==OrderStatus.OUT_FOR_DELIVERY)&&status==OrderStatus.COMPLETED);if(!allowed){ra.addFlashAttribute("errorMessage","That status change is not allowed from the current order stage.");return "redirect:/vendor/orders";}o.setStatus(status);if(status==OrderStatus.COMPLETED){o.setCompletedAt(Instant.now());o.setCommissionRatePercent(commissions.getRatePercent());}o.setUpdatedAt(Instant.now());orders.save(o);if(status==OrderStatus.COMPLETED&&o.getPaymentStatus()==PaymentStatus.VERIFIED)commissions.recordCompletedOrder(o);ra.addFlashAttribute("successMessage","Order status updated.");return "redirect:/vendor/orders";}
 @PostMapping("/customer/orders/{id}/upi-proof") public String resubmitUpiProof(@PathVariable String id,@RequestParam String upiReference,@RequestParam MultipartFile paymentProof,Principal principal,RedirectAttributes ra){UserAccount buyer=current(principal);if(buyer.getRole()!=Role.ROLE_CUSTOMER)return "auth/access-denied";MarketplaceOrder o=orders.findById(id).orElseThrow();if(!buyer.getId().equals(o.getCustomerUserId()))return "auth/access-denied";if(o.getPaymentMethod()!=PaymentMethod.UPI||o.getPaymentStatus()!=PaymentStatus.REJECTED||o.getStatus()==OrderStatus.CANCELLED){ra.addFlashAttribute("errorMessage","This order is not eligible for UPI evidence resubmission.");return "redirect:/customer/orders";}try{if(blank(upiReference)||upiReference.trim().length()>100)throw new IllegalArgumentException("Enter a valid UPI UTR/reference.");Map<String,Object> proof=uploads.uploadDocument(paymentProof,"asmj-marketplace/order-payments");o.setUpiReference(upiReference.trim());o.setPaymentProofUrl(String.valueOf(proof.get("secure_url")));o.setPaymentProofFileName(paymentProof.getOriginalFilename());o.setPaymentStatus(PaymentStatus.PROOF_SUBMITTED);o.setUpdatedAt(Instant.now());orders.save(o);ra.addFlashAttribute("successMessage","Updated UPI evidence submitted for admin verification.");}catch(IllegalArgumentException|IllegalStateException ex){ra.addFlashAttribute("errorMessage",ex.getMessage());}return "redirect:/customer/orders";}
 @PostMapping("/vendor/orders/{id}/cash-receipt") public String cashReceipt(@PathVariable String id,@RequestParam MultipartFile receipt,@RequestParam(required=false) String note,Principal principal,RedirectAttributes ra){UserAccount u=current(principal);if(u.getRole()!=Role.ROLE_VENDOR)return "auth/access-denied";MarketplaceOrder o=orders.findById(id).orElseThrow();if(!u.getId().equals(o.getVendorUserId()))return "auth/access-denied";if(o.getPaymentMethod()!=PaymentMethod.COD||o.getStatus()!=OrderStatus.COMPLETED){ra.addFlashAttribute("errorMessage","Cash receipt can be uploaded only for a completed COD order.");return "redirect:/vendor/orders";}try{Map<String,Object> file=uploads.uploadDocument(receipt,"asmj-marketplace/cash-receipts");o.setCashReceiptUrl(String.valueOf(file.get("secure_url")));o.setCashReceiptFileName(receipt.getOriginalFilename());o.setCashReceiptNote(note==null?"":note.trim());o.setCashReceivedBy(u.getFullName());o.setCashReceivedAt(Instant.now());o.setPaymentStatus(PaymentStatus.VERIFIED);o.setUpdatedAt(Instant.now());orders.save(o);commissions.recordCompletedOrder(o);ra.addFlashAttribute("successMessage","Cash receipt uploaded and payment recorded.");}catch(IllegalArgumentException|IllegalStateException ex){ra.addFlashAttribute("errorMessage",ex.getMessage());}return "redirect:/vendor/orders";}
 @PostMapping("/customer/orders/{id}/cancel") public String cancel(@PathVariable String id,Principal p,RedirectAttributes ra){UserAccount u=current(p);MarketplaceOrder o=orders.findById(id).orElseThrow();if(!u.getId().equals(o.getCustomerUserId()))return "auth/access-denied";if(o.getStatus()!=OrderStatus.PLACED){ra.addFlashAttribute("errorMessage","Only newly placed orders can be cancelled. Contact support for assistance.");return "redirect:/customer/orders";}o.setStatus(OrderStatus.CANCELLED);o.setUpdatedAt(Instant.now());orders.save(o);ra.addFlashAttribute("successMessage","Order cancelled. Please contact the vendor about any refund for a UPI payment.");return "redirect:/customer/orders";}
 @PostMapping("/admin/orders/{id}/payment-status") public String paymentStatus(@PathVariable String id,@RequestParam PaymentStatus status,RedirectAttributes ra){MarketplaceOrder o=orders.findById(id).orElseThrow();if(o.getPaymentMethod()!=PaymentMethod.UPI||!Set.of(PaymentStatus.VERIFIED,PaymentStatus.REJECTED).contains(status)){ra.addFlashAttribute("errorMessage","Invalid payment review action.");return "redirect:/admin/orders";}o.setPaymentStatus(status);o.setUpdatedAt(Instant.now());orders.save(o);if(status==PaymentStatus.VERIFIED&&o.getStatus()==OrderStatus.COMPLETED)commissions.recordCompletedOrder(o);ra.addFlashAttribute("successMessage","Payment status updated.");return "redirect:/admin/orders";}
 private UserAccount current(Principal p){UserAccount u=users.findByEmailIgnoreCase(p.getName()).orElseThrow();if(u.getRole()!=Role.ROLE_CUSTOMER&&u.getRole()!=Role.ROLE_VENDOR)throw new IllegalArgumentException("Customer account required.");return u;}
 private boolean blank(String s){return s==null||s.isBlank();} private List<Map<String,Object>> cartRows(HttpSession s){List<Map<String,Object>> rows=new ArrayList<>();for(var e:cart(s).entrySet()){Product p=products.findById(e.getKey()).orElse(null);if(p!=null){Map<String,Object> r=new HashMap<>();r.put("product",p);r.put("quantity",e.getValue());r.put("lineTotal",p.getPrice().multiply(BigDecimal.valueOf(e.getValue())));rows.add(r);}}return rows;}private BigDecimal cartSubtotal(HttpSession s){return cartRows(s).stream().map(r->(BigDecimal)r.get("lineTotal")).reduce(BigDecimal.ZERO,BigDecimal::add);}
}
